/* Optional connected workflows. All network calls go through the same-origin API. */
(() => {
  'use strict';
  if(window.AfterwordRuntime?.offline)return;
  const O = () => window.AfterwordOutreach;
  const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const call = (path, body, method='POST') => O().api(path, {method, ...(body !== undefined ? {body} : {}), long:true});
  const btn = (id, label, primary=false) => `<button type="button" id="${id}" class="button ${primary?'primary':''}">${label}</button>`;
  const statusBox = () => '<p id="integration-status" role="status" aria-live="polite" class="fine"></p>';
  const status = text => { const box=document.getElementById('integration-status'); if(box) box.textContent=text; };
  const bind = (id, handler) => document.getElementById(id)?.addEventListener('click', async event => {
    const button=event.currentTarget; button.disabled=true;
    try {await handler();} catch(error){status(error.message || 'The request could not be completed.');} finally {if(button.isConnected)button.disabled=false;}
  });
  const actorInput = actor => `<label class="field-label" for="integration-actor">Your name</label><input id="integration-actor" class="input" maxlength="100" autocomplete="name" value="${esc(actor)}">`;
  const actor = () => {const value=document.getElementById('integration-actor')?.value.trim();if(!value)throw Error('Enter the name of the person approving this request.');return value;};
  const openLink = (id, label, href) => `<a id="${id}" class="button primary" href="${esc(href)}" target="_blank" rel="noopener noreferrer">${label}</a>`;

  async function lookup({finding_id, provider, onComplete}) {
    const integrations=await call('/integrations/status',undefined,'GET');
    if(!integrations.lookup_configured) {
      modal('Public contact lookup','<p>Public lookup is not configured on the local service. You can use an address from a document, the offline directory, or one you have verified yourself.</p>',button('Close','close-modal'));
      return;
    }
    modal('Look up a public contact',`<p>Only the company name and country will be sent to the configured search service. Family names, records, policy references and the letter stay here.</p><label class="field-label" for="lookup-country">Provider country</label><select id="lookup-country" class="input"><option value="US">United States</option><option value="CA">Canada</option><option value="GB">United Kingdom</option><option value="IN">India</option><option value="AU">Australia</option></select>${actorInput(O().currentDraft()?.fields?.writer_name||'')}<div id="lookup-preview"></div>${statusBox()}`,button('Not yet','close-modal')+btn('lookup-proceed','Approve public lookup',true));
    let preview=null;
    const load=async()=> {preview=null;document.getElementById('lookup-proceed').disabled=true;const country=document.getElementById('lookup-country').value;const value=await call('/providers/lookup-preview?'+new URLSearchParams({finding_id,country}),undefined,'GET');if(!document.getElementById('lookup-preview')||document.getElementById('lookup-country').value!==country)return;preview=value;document.getElementById('lookup-preview').innerHTML=`<p class="fine">Exactly what leaves this device</p><pre style="white-space:pre-wrap;overflow-wrap:anywhere">${esc(value.query)}</pre><p class="fine">Returned contacts are unverified until you check the source.</p>`;document.getElementById('lookup-proceed').disabled=false;};
    document.getElementById('lookup-country').addEventListener('change',()=>load().catch(error=>status(error.message)));
    bind('lookup-proceed',async()=>{if(!preview)throw Error('Wait for the lookup preview.');const result=await call('/providers/lookup',{finding_id,country:preview.payload.country,approved:true,actor:actor(),preview_hash:preview.preview_hash});await onComplete?.();modal('Public lookup completed',result.candidates.length?`<p>${result.candidates.length} public contact${result.candidates.length===1?'':'s'} found. Verify the source before using an address.</p>${result.candidates.map(candidate=>`<p><strong>${esc(candidate.channels[0].value)}</strong><br><a href="${esc(candidate.evidence[0].url)}" target="_blank" rel="noopener noreferrer">View public source</a> · Please verify</p>`).join('')}`:'<p>No usable address was found. Nothing has been sent to a provider.</p>',button('Return to letter','close-modal'));});
    await load();
  }

  async function gmailSettings() {
    const info=await call('/integrations/gmail/status',undefined,'GET');
    O().setGmailStatus?.(info);
    modal('Gmail connection',`<p>${info.configured?(info.connected?'Gmail is connected to this local service.':'Connect Gmail to create reviewed drafts from Afterword.'):'Gmail API drafts need an OAuth client configured on the local service. You can still use Open in Gmail without an account connection.'}</p><p class="fine">${esc(info.permission_notice)}</p>${info.configured?actorInput(O().currentDraft()?.fields?.writer_name||''):''}<dl class="privacy-facts"><div><dt>Draft creation</dt><dd>${info.draft_scope_granted?'Permission granted':'Not connected'}</dd></div><div><dt>Reply tracking</dt><dd>${info.reply_tracking_granted?'Separate read permission granted':'Off — your mailbox is not read'}</dd></div></dl><p class="fine">Enabling reply tracking asks Google for access to read your mailbox. Afterword checks only the message created here and its replies when you request a check.</p>${statusBox()}`,button('Close','close-modal')+(info.configured?btn('gmail-connect','Approve draft connection',true)+(!info.reply_tracking_granted?btn('gmail-readonly','Approve reply tracking'):''):'')+(info.connected?btn('gmail-disconnect','Disconnect Gmail'):''));
    const connect=async purpose=>{const result=await call('/integrations/gmail/authorize',{purpose,approved:true,actor:actor()});const parsed=new URL(result.authorization_url);if(parsed.origin!=='https://accounts.google.com')throw Error('The authorization link is invalid.');status('Continue to Google to choose your account and review permissions.');document.getElementById('integration-status').insertAdjacentHTML('afterend',openLink('gmail-authorize-link','Continue to Google',result.authorization_url));};
    bind('gmail-connect',()=>connect('drafts'));
    bind('gmail-readonly',()=>connect('reply_tracking'));
    bind('gmail-disconnect',async()=>{const result=await call('/integrations/gmail/disconnect',{});O().setGmailStatus?.(await call('/integrations/gmail/status',undefined,'GET'));modal('Gmail disconnected',`<p>${esc(result.note)}</p><p>Local access tokens were deleted. Existing Gmail drafts remain in your mailbox.</p>`,button('Close','close-modal'));});
  }

  async function gmailDraft({draft, onComplete}) {
    const info=await call('/integrations/gmail/status',undefined,'GET');
    if(!info.connected || !info.draft_scope_granted) {await gmailSettings();return;}
    let attached=[...(draft.attachment_files||[])], reviewIds=new Map(), finalReview=null, pendingConsent=null;
    const path='/outreach/'+encodeURIComponent(draft.id);
    const refresh=async()=>{const priorHash=finalReview?.snapshot_hash;finalReview=await call(path+'/review',{});if(priorHash!==finalReview.snapshot_hash)pendingConsent=null;attached=finalReview.snapshot.attachment_files||[];O().storeDraft({...draft,...finalReview.snapshot},'server');const list=document.getElementById('gmail-file-list');if(!list)return;list.innerHTML=attached.length?attached.map(file=>`<article class="outreach-history-row"><div><strong>${esc(file.name)}</strong><p class="fine">${(file.size/1024).toFixed(1)} KB · SHA-256 ${esc(file.sha256.slice(0,12))}…</p><a class="text-link" href="${path}/attachments/${encodeURIComponent(file.id)}" download rel="noopener">Download to review</a><label style="display:block;margin-top:10px"><input type="checkbox" data-file-review="${esc(file.id)}" ${reviewIds.has(file.id)?'checked':''}> I opened and reviewed this exact file.</label><button type="button" class="button" data-remove-file="${esc(file.id)}">Remove</button></div></article>`).join(''):'<p class="fine">No files will be shared. Checklist items in the letter are reminders only.</p>';document.getElementById('gmail-final-body').textContent=finalReview.snapshot.body;document.getElementById('gmail-final-to').textContent=finalReview.snapshot.recipient;document.getElementById('gmail-final-subject').textContent=finalReview.snapshot.subject;document.getElementById('gmail-final-sharing').textContent=finalReview.disclosed_fields.join(', ');document.getElementById('gmail-create').disabled=!finalReview.can_handoff;};
    modal('Review your Gmail draft',`<p>Creating this draft shares the following letter and any reviewed files with Google. Nothing is sent to the provider until you press Send in Gmail.</p><dl class="privacy-facts"><div><dt>To</dt><dd id="gmail-final-to"></dd></div><div><dt>Subject</dt><dd id="gmail-final-subject"></dd></div></dl><pre id="gmail-final-body" style="white-space:pre-wrap;overflow-wrap:anywhere;max-height:280px;overflow:auto"></pre><p><strong>What you’re sharing</strong><br><span id="gmail-final-sharing"></span></p><p class="fine">Read the complete letter and every file. The field summary cannot detect every personal detail.</p><section><h3>Files to include</h3><p class="fine">Optional. PDF, text, PNG or JPEG; five files and 10 MB total. Files stay on the local service until you approve this draft.</p><label class="field-label" for="gmail-add-file">Choose a file</label><input id="gmail-add-file" type="file" accept=".pdf,.txt,.png,.jpg,.jpeg"><div id="gmail-file-list"></div></section><label style="display:block;margin-top:18px"><input id="gmail-final-confirm" type="checkbox"> I verified the recipient and approve sharing this letter and the selected files with Google.</label>${actorInput(draft.fields?.writer_name||'')}${statusBox()}`,button('Not yet','close-modal')+btn('gmail-create','Create reviewed Gmail draft',true));
    await refresh();
    document.getElementById('gmail-add-file').addEventListener('change',async event=>{const file=event.target.files[0];if(!file)return;try {if(file.size>10000000)throw Error('Choose a file smaller than 10 MB.');status('Saving the file on your local service…');const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));await call(path+'/attachments',{name:file.name,content_base64:btoa(binary)});document.getElementById('gmail-final-confirm').checked=false;await refresh();status('File saved locally. Download and review it before approving.');}catch(error){status(error.message);}finally{event.target.value='';}});
    document.getElementById('gmail-file-list').addEventListener('change',async event=>{const id=event.target.dataset.fileReview;if(!id)return;try{if(!event.target.checked){reviewIds.delete(id);return;}const file=attached.find(item=>item.id===id);const recorded=await call(path+'/attachments/'+encodeURIComponent(id)+'/review',{sha256:file.sha256,reviewed:true,actor:actor()});reviewIds.set(id,recorded.id);}catch(error){event.target.checked=false;status(error.message);}});
    document.getElementById('gmail-file-list').addEventListener('click',async event=>{const target=event.target.closest('[data-remove-file]');if(!target)return;target.disabled=true;try{await call(path+'/attachments/'+encodeURIComponent(target.dataset.removeFile),{},'DELETE');reviewIds.delete(target.dataset.removeFile);document.getElementById('gmail-final-confirm').checked=false;await refresh();}catch(error){status(error.message);target.disabled=false;}});
    bind('gmail-create',async()=>{if(!document.getElementById('gmail-final-confirm').checked)throw Error('Confirm the recipient and disclosure before continuing.');if(attached.some(file=>!reviewIds.has(file.id)))throw Error('Open and review each attached file first.');const person=actor();if(pendingConsent&&pendingConsent.actor!==person)throw Error('This draft request is unresolved. Check Gmail before starting a new review with another approver.');const approved=pendingConsent||await call(path+'/consent',{snapshot_hash:finalReview.snapshot_hash,actor:person,channel:'gmail_api',recipient_confirmed:true});pendingConsent=approved;status('Creating the reviewed draft in Gmail…');const result=await call(path+'/gmail-draft',{consent_id:approved.id,snapshot_hash:finalReview.snapshot_hash,attachment_review_ids:attached.map(file=>reviewIds.get(file.id))});const completedDraft={...draft,...finalReview.snapshot};O().log('gmail_draft_created',completedDraft,{consent_id:approved.id});await onComplete?.({draft:completedDraft,consent:approved,result});await O().refreshPrivacy?.();modal('Your Gmail draft is ready',`<p>In the Google account <strong>${esc(result.sender)}</strong>, open Drafts and choose <strong>${esc(result.subject)}</strong>.</p><p>Read it once more, then press Send in Gmail when you are ready. Return here and mark it as sent afterward.</p><p class="fine">${esc(result.link_note)}</p>`,button('Close','close-modal')+openLink('gmail-open-drafts','Open Gmail Drafts',result.gmail_url));});
  }

  async function checkReply({draft,onComplete}) {
    const result=await call('/outreach/'+encodeURIComponent(draft.id)+'/check-reply',{});
    await onComplete?.(result);
    modal(result.replied?'A reply was found':'Reply check',`<p>${esc(result.replied?'An incoming reply matched the recipient and the sent message.':result.reason||'No matching incoming reply has been found yet.')}</p><p class="fine">If the provider replied from another address or Gmail changed the message identifier, you can still mark the reply manually.</p>`,button('Close','close-modal')+(result.gmail_url?openLink('gmail-open-thread','Open Gmail',result.gmail_url):''));
  }

  const guarded=handler=>async options=>{try{return await handler(options);}catch(error){modal('Connection unavailable',`<p>${esc(error.message||'The local service could not complete this request.')}</p><p>Your letter is still available. Nothing has been sent by Afterword.</p>`,button('Close','close-modal'));}};
  window.AfterwordOutreachIntegrations={lookup:guarded(lookup),gmailSettings:guarded(gmailSettings),gmailDraft:guarded(gmailDraft),checkReply:guarded(checkReply)};
})();
